function kthFactor(n, k) {
  const small = [];
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      small.push(i);
    }
  }
  const root = small[small.length - 1];
  const total = root * root === n ? 2 * small.length - 1 : 2 * small.length;
  if (k > total) {
    return -1;
  }
  if (k <= small.length) {
    return small[k - 1];
  }
  return n / small[total - k];
}

