function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const rich = [720, 840, 960, 1000, 900, 576, 625, 961, 997, 512];
  let n;
  if (size === 'large') n = rand() < 0.4 ? rich[int(0, rich.length - 1)] : int(500, 1000);
  else n = int(1, 60);
  let count = 0;
  for (let i = 1; i <= n; i++) if (n % i === 0) count++;
  const k = rand() < 0.75 ? int(1, Math.min(n, count)) : int(1, Math.min(n, count + 3));
  return [n, k];
}
